@dataclass
class _EpochState:
    """Internal mutable state for an epoch's lifecycle."""
    id: str
    node_name: str
    in_salvo: Any
    out_salvos: list
    state: Any           # EpochState — updated at each transition
    orphaned_packets: list
    created_at: datetime
    logs: list[tuple[datetime, str]] = field(default_factory=list)
    was_cancelled: bool = False
    started_at: datetime | None = None
    ended_at: datetime | None = None
    destroyed_packets: list[str] = field(default_factory=list)
    pool_id: str | None = None
    worker_id: int | None = None
    was_cache_hit: bool = False
    was_file_storage_hit: bool = False

    # Consolidated from previously-separate dicts:
    structured_logs: list = field(default_factory=list)  # was _epoch_log_buffers[epoch_id]
    net_actions: list = field(default_factory=list)       # was _epoch_net_actions[epoch_id]
    retry_state: dict = field(default_factory=dict)       # was _epoch_states[epoch_id] (ctx.state)

    @classmethod
    def from_epoch(cls, epoch) -> "_EpochState":
        """Create an _EpochState from a netrun_sim.Epoch object."""
        created_at = datetime.fromtimestamp(epoch.start_time() / 1000, tz=timezone.utc)
        return cls(
            id=str(epoch.id), node_name=epoch.node_name,
            in_salvo=epoch.in_salvo, out_salvos=list(epoch.out_salvos),
            state=epoch.state, orphaned_packets=list(epoch.orphaned_packets),
            created_at=created_at,
        )

    def start_time(self) -> int:
        """Creation timestamp in ms (compat with netrun_sim.Epoch)."""
        return int(self.created_at.timestamp() * 1000)

    def get_logs(self) -> list[tuple[datetime, str]]:
        """Return a copy of the print logs."""
        return list(self.logs)

    @property
    def pool_worker_label(self) -> str | None:
        """Human-readable label for pool/worker, or None if not set."""
        if self.pool_id is None:
            return None
        label = self.pool_id
        if self.worker_id is not None:
            label += f"/{self.worker_id}"
        return label

    def print_logs(self, include_timestamps: bool = True) -> None:
        """Print the logs to stdout.

        Args:
            include_timestamps: If True (default), prefix each line with its timestamp.
        """
        for timestamp, message in self.logs:
            if include_timestamps:
                print(f"[{timestamp.strftime('%H:%M:%S.%f')[:-3]}] {message.strip()}")
            else:
                print(message.strip())

    def to_log(
        self,
        *,
        node_log_entries: list[NodeLogEntry] | None = None,
        net_actions: list[NetActionLog] | None = None,
        factory: str | None = None,
        retry_count: int = 0,
        error: Exception | None = None,
    ) -> EpochLog:
        """Convert to an immutable EpochLog at epoch completion."""
        # Determine outcome
        if error is not None:
            outcome = "error"
        elif self.was_cache_hit:
            outcome = "cache_hit"
        elif self.was_file_storage_hit:
            outcome = "file_storage_hit"
        elif self.was_cancelled:
            outcome = "cancelled"
        else:
            outcome = "success"

        # Calculate timing
        duration_ms = None
        queue_time_ms = None
        if self.started_at and self.ended_at:
            duration_ms = (self.ended_at - self.started_at).total_seconds() * 1000
        if self.started_at:
            queue_time_ms = (self.started_at - self.created_at).total_seconds() * 1000

        node_log_entries = node_log_entries or []
        net_actions = net_actions or []

        # Merge user fields from all log entries
        user_fields: dict[str, Any] = {}
        for entry in node_log_entries:
            user_fields.update(entry.fields)

        # In salvo info
        in_salvo_ports: list[str] = []
        in_salvo_packet_count = 0
        if self.in_salvo:
            seen: set[str] = set()
            for port_name, _ in self.in_salvo.packets:
                if port_name not in seen:
                    in_salvo_ports.append(port_name)
                    seen.add(port_name)
                in_salvo_packet_count += 1

        return EpochLog(
            epoch_id=self.id,
            node_name=self.node_name,
            timestamp=self.ended_at or self.created_at,
            created_at=self.created_at,
            started_at=self.started_at,
            ended_at=self.ended_at,
            duration_ms=duration_ms,
            queue_time_ms=queue_time_ms,
            outcome=outcome,
            error=str(error) if error else None,
            error_type=type(error).__name__ if error else None,
            error_traceback="".join(traceback.format_exception(error)) if error else None,
            pool_id=self.pool_id,
            worker_id=self.worker_id,
            retry_count=retry_count,
            was_cache_hit=self.was_cache_hit,
            was_file_storage_hit=self.was_file_storage_hit,
            in_salvo_ports=in_salvo_ports,
            in_salvo_packet_count=in_salvo_packet_count,
            out_salvo_count=len(self.out_salvos),
            orphaned_packet_count=len(self.orphaned_packets),
            destroyed_packet_count=len(self.destroyed_packets),
            factory=factory,
            node_log_entries=node_log_entries,
            user_fields=user_fields,
            net_actions=net_actions,
            logs=list(self.logs),
        )


