@dataclass
class NetFuncPreprocessorNodeConfig:
    """Picklable configuration for a node's preprocessor behavior.

    This captures only the serializable parts needed for preprocessing,
    avoiding closures that can't be pickled for multiprocess pools.
    """
    factory: str | None
    """Factory module path for lazy resolution (None if not factory-based)."""

    factory_args: dict[str, Any]
    """Arguments to pass to factory's get_node_funcs()."""

    out_ports: dict[str, dict[str, Any]]
    """Output port configs (serialized as dicts for pickling)."""

    in_ports: dict[str, dict[str, Any]] = field(default_factory=dict)
    """Input port configs (serialized as dicts for pickling)."""

    # Copy of NodeExecutionConfig fields needed for context creation
    print_echo_stdout: bool = False
    retries: int = 0
    retry_wait: float = 0.0
    timeout: float | None = None

    node_vars: dict[str, dict[str, str]] | None = None
    """Merged node variables (serialized as dicts for pickling)."""

    type_checking_enabled: bool = True
    """Whether type checking is enabled for this node."""

    net_config_data: dict | None = None
    """Serialized NetConfig data (model_dump()) for reconstructing NetConfig on workers.
    Used to pass _net_config to factory get_node_funcs() during lazy resolution."""

    @classmethod
    def from_node_config(
        cls,
        exec_config: NodeExecutionConfig,
        in_ports: dict[str, PortConfig],
        out_ports: dict[str, PortConfig],
        factory: str | None,
        factory_args: dict[str, Any],
        node_vars: dict[str, dict[str, str]] | None = None,
        effective_fields: dict[str, Any] | None = None,
        net_config_data: dict | None = None,
    ) -> "NetFuncPreprocessorNodeConfig":
        """Create from execution config, port configs, and factory info.

        Args:
            effective_fields: Resolved inheritable fields (from resolve_effective_exec_field).
                Keys are field names, values are the effective (merged) values.
        """
        ef = effective_fields or {}
        return cls(
            factory=factory,
            factory_args=factory_args,
            in_ports={name: port.model_dump() for name, port in in_ports.items()},
            out_ports={name: port.model_dump() for name, port in out_ports.items()},
            print_echo_stdout=ef.get("print_echo_stdout", False),
            retries=ef.get("retries", 0),
            retry_wait=ef.get("retry_wait", 0.0),
            timeout=ef.get("timeout", None),
            node_vars=node_vars,
            type_checking_enabled=ef.get("type_checking_enabled", True),
            net_config_data=net_config_data,
        )


class NetFuncPreprocessor:
    """Picklable func_preprocessor for Net execution.

    Unlike the closure-based version, this class can be pickled for multiprocess pools.
    It resolves factory-based node functions lazily on each worker.

    Provides two wrapper modes:
    - __call__: returns async wrapper (for SingleWorkerPool / async contexts)
    - call_for_sync_worker: returns sync wrapper (for ThreadPool / MultiprocessPool)
      Async user functions are dispatched to _shared_loop via run_coroutine_threadsafe.
      Sync user functions run directly in the calling thread.
    """

    def __init__(
        self,
        node_configs: dict[str, NetFuncPreprocessorNodeConfig],
    ):
        """Initialize the preprocessor.

        Args:
            node_configs: Mapping of node names to their preprocessor configs.
        """
        self._node_configs = node_configs
        # Worker-local cache for resolved factory functions
        self._resolved_funcs: dict[str, Callable] = {}
        # Shared event loop for async dispatch (set by worker on startup)
        self._shared_loop: asyncio.AbstractEventLoop | None = None

    def _resolve_factory(self, node_name: str) -> Callable | None:
        """Resolve factory function on worker (lazy).

        Called on first use for each node on each worker.
        """
        if node_name in self._resolved_funcs:
            return self._resolved_funcs[node_name]

        config = self._node_configs.get(node_name)
        if config is None or config.factory is None:
            return None

        # Reconstruct NetConfig from serialized data for _net_config
        net_config = None
        if config.net_config_data is not None:
            from ...net.config import NetConfig
            net_config = NetConfig.model_validate(config.net_config_data)

        # Import factory module and call get_node_funcs
        module = importlib.import_module(config.factory)
        get_node_funcs = getattr(module, "get_node_funcs")
        exec_func, _, _, _ = get_node_funcs(_net_config=net_config, **config.factory_args)

        self._resolved_funcs[node_name] = exec_func
        return exec_func

    def _setup_context(
        self,
        exec_node_func: Callable,
        epoch_id: str,
        node_name: str,
        packets: dict[str, list[str]],
        packet_values: dict[str, Any],
        retry_count: int,
        retry_timestamps: list[datetime] | None,
        retry_exceptions: list[Exception] | None,
        state: dict[str, Any] | None = None,
    ) -> tuple[NodeExecutionContext, Callable]:
        """Common setup for both sync and async wrappers.

        Returns:
            (ctx, actual_func) — the execution context and resolved function.
        """
        config = self._node_configs.get(node_name)
        in_ports = {}
        out_ports = {}
        if config:
            in_ports = {
                name: PortConfig.model_validate(port_dict)
                for name, port_dict in config.in_ports.items()
            }
            out_ports = {
                name: PortConfig.model_validate(port_dict)
                for name, port_dict in config.out_ports.items()
            }

        # Create execution config for context (with essential fields)
        exec_config = None
        if config:
            exec_config = NodeExecutionConfig(
                print_echo_stdout=config.print_echo_stdout,
                retries=config.retries,
                retry_wait=config.retry_wait,
                timeout=config.timeout,
            )

        # Reconstruct NodeVariable objects from serialized dicts
        _node_vars = None
        if config and config.node_vars:
            _node_vars = {
                n: NodeVariable.model_validate(v)
                for n, v in config.node_vars.items()
            }

        # Get type checking enabled flag (default True if no config)
        type_checking_enabled = config.type_checking_enabled if config else True

        ctx = NodeExecutionContext(
            epoch_id=epoch_id,
            node_name=node_name,
            retry_count=retry_count,
            retry_timestamps=retry_timestamps or [],
            retry_exceptions=retry_exceptions or [],
            state=state if state is not None else {},
            _config=exec_config,
            _input_packet_values=packet_values,
            _in_ports=in_ports,
            _out_ports=out_ports,
            _node_vars=_node_vars,
            _type_checking_enabled=type_checking_enabled,
        )

        # Determine the actual function to call
        actual_func = exec_node_func
        if isinstance(exec_node_func, _FactoryPlaceholder):
            resolved = self._resolve_factory(node_name)
            if resolved is None:
                raise RuntimeError(
                    f"Failed to resolve factory function for node '{node_name}'"
                )
            actual_func = resolved

        return ctx, actual_func

    @staticmethod
    def _build_result(
        ctx: NodeExecutionContext,
        func_result: Any,
        exception: Exception | None,
    ) -> NodeExecutionResult:
        """Build NodeExecutionResult from context and execution outcome."""
        result = ctx._get_execution_result()
        result.func_result = func_result
        result.exception = exception
        return result

    def __call__(self, exec_node_func: Callable) -> Callable:
        """Return an async wrapper for SingleWorkerPool (async context).

        The wrapper awaits async user functions and calls sync ones directly.
        """
        preprocessor_self = self

        async def wrapped(
            epoch_id: str,
            node_name: str,
            packets: dict[str, list[str]],
            packet_values: dict[str, Any],
            retry_count: int = 0,
            retry_timestamps: list[datetime] | None = None,
            retry_exceptions: list[Exception] | None = None,
            state: dict[str, Any] | None = None,
        ) -> NodeExecutionResult:
            ctx, actual_func = preprocessor_self._setup_context(
                exec_node_func, epoch_id, node_name, packets, packet_values,
                retry_count, retry_timestamps, retry_exceptions, state=state,
            )

            func_result = None
            exception = None

            try:
                ctx._validate_input_packets(packets)
                if asyncio.iscoroutinefunction(actual_func):
                    func_result = await actual_func(ctx, packets)
                else:
                    func_result = actual_func(ctx, packets)
            except EpochCancelled:
                pass
            except Exception as e:
                exception = e

            return preprocessor_self._build_result(ctx, func_result, exception)

        return wrapped

    def call_for_sync_worker(self, exec_node_func: Callable) -> Callable:
        """Return a sync wrapper for ThreadPool/MultiprocessPool (sync context).

        Sync user functions run directly in the calling worker thread.
        Async user functions are dispatched to the shared event loop via
        run_coroutine_threadsafe and the worker thread blocks on the result.
        """
        preprocessor_self = self

        def wrapped(
            epoch_id: str,
            node_name: str,
            packets: dict[str, list[str]],
            packet_values: dict[str, Any],
            retry_count: int = 0,
            retry_timestamps: list[datetime] | None = None,
            retry_exceptions: list[Exception] | None = None,
            state: dict[str, Any] | None = None,
        ) -> NodeExecutionResult:
            ctx, actual_func = preprocessor_self._setup_context(
                exec_node_func, epoch_id, node_name, packets, packet_values,
                retry_count, retry_timestamps, retry_exceptions, state=state,
            )

            func_result = None
            exception = None

            try:
                ctx._validate_input_packets(packets)
                if asyncio.iscoroutinefunction(actual_func):
                    if preprocessor_self._shared_loop is None:
                        raise RuntimeError(
                            f"Async node function '{node_name}' requires a shared event loop, "
                            "but none was set on the preprocessor. This is a netrun internal error."
                        )
                    coro = actual_func(ctx, packets)
                    future = asyncio.run_coroutine_threadsafe(coro, preprocessor_self._shared_loop)
                    func_result = future.result()
                else:
                    func_result = actual_func(ctx, packets)
            except EpochCancelled:
                pass
            except Exception as e:
                exception = e

            return preprocessor_self._build_result(ctx, func_result, exception)

        return wrapped


class _FactoryPlaceholder:
    """Placeholder for factory-based node functions.

    Registered with workers instead of actual functions when the node uses
    a factory. The NetFuncPreprocessor resolves the actual function lazily.
    """

    def __init__(self, node_name: str):
        self.node_name = node_name

    def __repr__(self) -> str:
        return f"_FactoryPlaceholder({self.node_name!r})"


def create_net_func_preprocessor(
    node_execution_configs: dict[str, NodeExecutionConfig],
    node_in_ports: dict[str, dict[str, PortConfig]] | None = None,
    node_out_ports: dict[str, dict[str, PortConfig]] | None = None,
    node_factories: dict[str, tuple[str, dict[str, Any]]] | None = None,
    net_node_vars: dict[str, NodeVariable] | None = None,
    net_config: Any = None,
    net_config_data: dict | None = None,
) -> NetFuncPreprocessor:
    """Create a func_preprocessor for Net execution.

    The preprocessor transforms `exec_node_func(ctx, packets)` into a wrapped function
    that:
    1. Creates a NodeExecutionContext with input packet values
    2. Validates input packet types against port configurations
    3. Runs the node function (resolving factory functions lazily)
    4. Returns NodeExecutionResult with deferred actions and print buffer

    Args:
        node_execution_configs: Mapping of node names to their execution configs.
        node_in_ports: Mapping of node names to their input port configs (for type validation).
        node_out_ports: Mapping of node names to their output port configs (for type validation).
        node_factories: Mapping of node names to (factory_path, factory_args) tuples for
            factory-based nodes. Factory functions are resolved lazily on workers.
        net_node_vars: Net-level default node variables.
        net_config: The resolved NetConfig, used for inheritable field resolution.
        net_config_data: Serialized NetConfig (model_dump()) for reconstructing on workers.
            Passed to factory get_node_funcs() as _net_config during lazy resolution.

    Returns:
        A picklable NetFuncPreprocessor instance.
    """
    node_in_ports = node_in_ports or {}
    node_out_ports = node_out_ports or {}
    node_factories = node_factories or {}

    # Convert to picklable config format
    node_configs = {}
    for node_name, config in node_execution_configs.items():
        in_ports = node_in_ports.get(node_name, {})
        out_ports = node_out_ports.get(node_name, {})
        factory_info = node_factories.get(node_name)
        factory = factory_info[0] if factory_info else None
        factory_args = factory_info[1] if factory_info else {}

        # Merge net-level + node-level vars (node overrides net, inherit-aware)
        merged_vars = None
        if net_node_vars or config.node_vars:
            merged = {}
            if net_node_vars:
                merged.update({k: v.model_dump() for k, v in net_node_vars.items()})
            if config.node_vars:
                for k, v in config.node_vars.items():
                    if v.inherit:
                        if net_node_vars and k in net_node_vars:
                            global_var = net_node_vars[k]
                            if v.value is not None:
                                # Override just the value, use global type/options/optional
                                effective = NodeVariable(
                                    value=v.value,
                                    type=global_var.type,
                                    options=global_var.options,
                                    optional=global_var.optional,
                                )
                                merged[k] = effective.model_dump()
                            # else: global already in merged, keep it
                        else:
                            raise ValueError(
                                f"Node '{node_name}' variable '{k}' has inherit=True "
                                f"but no net-level variable '{k}' exists"
                            )
                    else:
                        merged[k] = v.model_dump()
            if merged:
                merged_vars = merged

        # Resolve all inheritable fields (node-level overrides net-level)
        effective = {
            fname: resolve_effective_exec_field(fname, config, net_config)
            for fname in INHERITABLE_EXEC_FIELDS
        }

        node_configs[node_name] = NetFuncPreprocessorNodeConfig.from_node_config(
            config, in_ports, out_ports, factory, factory_args,
            node_vars=merged_vars,
            effective_fields=effective,
            net_config_data=net_config_data,
        )

    return NetFuncPreprocessor(node_configs)
